import{_ as o,o as d,c as e,ai as r}from"./chunks/framework.ampVZV4B.js";const h=JSON.parse('{"title":"03 模型选择指南：按环境与使用场景选型","description":"","frontmatter":{},"headers":[],"relativePath":"ai/explore/model-selection.md","filePath":"ai/explore/model-selection.md"}'),l={name:"ai/explore/model-selection.md"};function a(n,t,i,s,g,c){return d(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="_03-模型选择指南-按环境与使用场景选型" tabindex="-1">03 模型选择指南：按环境与使用场景选型 <a class="header-anchor" href="#_03-模型选择指南-按环境与使用场景选型" aria-label="Permalink to “03 模型选择指南：按环境与使用场景选型”">​</a></h1><blockquote><p>目标：你能在不同环境下（本地/云端/混合），按任务（写代码/写文档/图片生成/视频生成/RAG/Agent）选到&quot;够用且稳定&quot;的模型，并且知道 <strong>2026 当下优先用哪些模型</strong>（不追新、不踩坑）。</p></blockquote><blockquote><p>注：模型更新很快，这篇给的是 <strong>&quot;优先级 + 可落地候选清单&quot;</strong>。你只要在同一梯队里换成你能用的提供方即可。</p></blockquote><h2 id="_1-先定-3-个变量-不定这三个-选型一定乱" tabindex="-1">1）先定 3 个变量（不定这三个，选型一定乱） <a class="header-anchor" href="#_1-先定-3-个变量-不定这三个-选型一定乱" aria-label="Permalink to “1）先定 3 个变量（不定这三个，选型一定乱）”">​</a></h2><ul><li><strong>环境</strong>：本地 / 云端 / 混合</li><li><strong>任务</strong>：代码、文档写作、图片生成、视频生成、问答、RAG、Agent 多步任务</li><li><strong>约束</strong>：隐私、预算、延迟、上下文长度</li></ul><h2 id="_1-1-一张-先选环境-再选模型-的决策树-最少纠结版" tabindex="-1">1.1 一张&quot;先选环境，再选模型&quot;的决策树（最少纠结版） <a class="header-anchor" href="#_1-1-一张-先选环境-再选模型-的决策树-最少纠结版" aria-label="Permalink to “1.1 一张&quot;先选环境，再选模型&quot;的决策树（最少纠结版）”">​</a></h2><ul><li><strong>必须本地（隐私/离线）？</strong><ul><li><strong>是</strong>：优先选 <strong>Qwen（中文强）/ Llama（通用强）/ DeepSeek（推理/代码常见）</strong> 的中小尺寸，先跑通。</li><li><strong>否</strong>：优先走云端（稳定、长上下文、能力更强）。</li></ul></li><li><strong>是否要做 Agent（工具调用/结构化输出）？</strong><ul><li><strong>是</strong>：优先选&quot;工具调用稳定/格式稳定&quot;的强模型（云端更省心），本地则优先选对齐更好的通用模型，不要上太小的&quot;玩具模型&quot;。</li></ul></li><li><strong>是否要做 RAG？</strong><ul><li><strong>是</strong>：选型重点是 <strong>上下文窗口 + 稳定性</strong>；不要指望&quot;大模型自己检索&quot;。</li></ul></li><li><strong>是否需要生成图片/视频？</strong><ul><li><strong>是</strong>：图片/视频模型目前几乎全部走云端 API（算力需求极高），本地仅支持 Stable Diffusion / ComfyUI 等开源图片方案（需高端显卡）。</li></ul></li></ul><h2 id="_1-2-2026-主流-llm-模型梯队" tabindex="-1">1.2）2026 主流 LLM 模型梯队 <a class="header-anchor" href="#_1-2-2026-主流-llm-模型梯队" aria-label="Permalink to “1.2）2026 主流 LLM 模型梯队”">​</a></h2><blockquote><p>以下梯队表侧重 <strong>文本/多模态 LLM</strong>（代码、写作、RAG、Agent）。图片/视频生成模型见 §3.3 / §3.4。</p></blockquote><h3 id="第一梯队-综合能力最强" tabindex="-1">第一梯队：综合能力最强 <a class="header-anchor" href="#第一梯队-综合能力最强" aria-label="Permalink to “第一梯队：综合能力最强”">​</a></h3><table tabindex="0"><thead><tr><th>模型</th><th>擅长领域</th><th>推荐场景</th><th>注意</th></tr></thead><tbody><tr><td><strong>GPT-4o</strong></td><td>代码、推理、多模态</td><td>关键任务、复杂重构</td><td>云端 API，成本较高</td></tr><tr><td><strong>Claude 3.5+ / 4</strong></td><td>长文本、写作、对齐</td><td>文档生成、代码审查</td><td>长上下文表现优异</td></tr><tr><td><strong>Gemini 2.5 Pro</strong></td><td>多模态、超长上下文</td><td>视频理解、超大文档</td><td>Google 生态集成</td></tr></tbody></table><h3 id="第二梯队-性价比之选" tabindex="-1">第二梯队：性价比之选 <a class="header-anchor" href="#第二梯队-性价比之选" aria-label="Permalink to “第二梯队：性价比之选”">​</a></h3><table tabindex="0"><thead><tr><th>模型</th><th>擅长领域</th><th>推荐场景</th><th>注意</th></tr></thead><tbody><tr><td><strong>DeepSeek-V3 / R1</strong></td><td>代码、推理</td><td>日常编码、批量任务</td><td>性价比极高，中文友好</td></tr><tr><td><strong>Qwen 2.5 / 3</strong></td><td>中文、工具调用</td><td>国内场景、RAG、Agent</td><td>开源可本地部署</td></tr><tr><td><strong>Llama 4</strong></td><td>通用、生态</td><td>本地部署、实验</td><td>开源社区支持最好</td></tr></tbody></table><h3 id="第三梯队-轻量与专用" tabindex="-1">第三梯队：轻量与专用 <a class="header-anchor" href="#第三梯队-轻量与专用" aria-label="Permalink to “第三梯队：轻量与专用”">​</a></h3><table tabindex="0"><thead><tr><th>模型</th><th>擅长领域</th><th>推荐场景</th><th>注意</th></tr></thead><tbody><tr><td><strong>Phi-4</strong></td><td>轻量推理</td><td>边缘设备、简单任务</td><td>微软出品，小而精</td></tr><tr><td><strong>Mistral Small / Large</strong></td><td>多语言、工具</td><td>欧洲场景、多语言</td><td>工具调用能力不错</td></tr><tr><td><strong>GLM-4</strong></td><td>中文</td><td>国内合规场景</td><td>智谱出品，本地友好</td></tr></tbody></table><h2 id="_2-按环境的选型策略" tabindex="-1">2）按环境的选型策略 <a class="header-anchor" href="#_2-按环境的选型策略" aria-label="Permalink to “2）按环境的选型策略”">​</a></h2><h3 id="_2-1-本地-优先-能跑-稳定" tabindex="-1">2.1 本地（优先&quot;能跑 + 稳定&quot;） <a class="header-anchor" href="#_2-1-本地-优先-能跑-稳定" aria-label="Permalink to “2.1 本地（优先&quot;能跑 + 稳定&quot;）”">​</a></h3><p>适合：</p><ul><li>笔记总结、面试题生成、轻量问答</li></ul><p>建议策略：</p><ul><li>先选&quot;中小参数&quot;模型跑通，再逐步上更强模型</li><li>若你要做 RAG：优先看上下文与速度是否可接受</li></ul><p>不建议本地硬扛：</p><ul><li>超长文档一次性输入</li><li>复杂多步推理（成本/时间会很高）</li></ul><h4 id="_2-1-1-2026-本地优先候选-按-好用-通用-中文" tabindex="-1">2.1.1 2026 本地优先候选（按&quot;好用/通用/中文&quot;） <a class="header-anchor" href="#_2-1-1-2026-本地优先候选-按-好用-通用-中文" aria-label="Permalink to “2.1.1 2026 本地优先候选（按&quot;好用/通用/中文&quot;）”">​</a></h4><ul><li><strong>通用 + 生态成熟</strong>：<code>Llama 3.x</code> / <code>Llama 4</code>（同梯队任选你能下载/能跑的版本）</li><li><strong>中文/工程落地友好</strong>：<code>Qwen2.x / Qwen2.5</code>（中文与工具类任务常见）</li><li><strong>代码/推理常见候选</strong>：<code>DeepSeek</code> 系列（常见于&quot;写代码/推理/成本&quot;权衡）</li><li><strong>低资源尝鲜</strong>：<code>Phi</code> / <code>Phi-4</code>、<code>Mistral 7B</code> 等小模型（适合&quot;草稿/结构化提取&quot;，不建议承担关键推理）</li></ul><p><strong>本地管理工具</strong>：<code>Ollama</code> + <code>Open WebUI</code>（拉模型、本地对话、简单管理，优先用这一套跑通）。</p><blockquote><p>选本地模型的要点：<strong>先选中等尺寸跑通闭环，再决定要不要上更大尺寸</strong>。你后面真正提效，更多来自&quot;Prompt/工具链/RAG&quot;，而不是盲目换更大的模型。</p></blockquote><h3 id="_2-2-云端-优先-质量-长上下文-稳定" tabindex="-1">2.2 云端（优先&quot;质量 + 长上下文 + 稳定&quot;） <a class="header-anchor" href="#_2-2-云端-优先-质量-长上下文-稳定" aria-label="Permalink to “2.2 云端（优先&quot;质量 + 长上下文 + 稳定&quot;）”">​</a></h3><p>适合：</p><ul><li>复杂代码生成/重构</li><li>长文档总结/对比</li><li>高质量面试回答打磨</li></ul><p>建议策略：</p><ul><li>把&quot;高价值任务&quot;放到云端强模型</li><li>把&quot;批量、重复、低价值任务&quot;留给本地/小模型</li></ul><h4 id="_2-2-1-2026-云端优先候选-按能力梯队" tabindex="-1">2.2.1 2026 云端优先候选（按能力梯队） <a class="header-anchor" href="#_2-2-1-2026-云端优先候选-按能力梯队" aria-label="Permalink to “2.2.1 2026 云端优先候选（按能力梯队）”">​</a></h4><ul><li><strong>高质量通用（代码/写作/多模态都强）</strong>：<code>GPT-4o</code>（同梯队的最新/可用版本优先）</li><li><strong>长文本/写作/对齐稳定</strong>：<code>Claude 3.x</code>（适合&quot;长文档对比/高质量润色/严谨表达&quot;）</li><li><strong>中文/性价比/国内可用性</strong>：<code>Qwen（通义）</code> 系列云端模型（适合&quot;中文业务/成本敏感/落地快&quot;）</li><li><strong>代码向/性价比</strong>：<code>DeepSeek</code> 系列云端模型（常见于&quot;代码 + 成本&quot;权衡）</li><li><strong>超长上下文 / Google 生态</strong>：<code>Gemini 2.5 Pro</code>（见 §1.2 第一梯队）</li><li><strong>国内合规</strong>：<code>GLM-4</code>（见 §1.2 第三梯队）</li></ul><blockquote><p>云端选型口诀：<strong>关键任务上强模型，批量任务用性价比模型</strong>。把&quot;路由策略&quot;写进你的 <code>LLM Gateway</code>，长期收益最大。</p></blockquote><h3 id="_2-3-混合-推荐" tabindex="-1">2.3 混合（推荐） <a class="header-anchor" href="#_2-3-混合-推荐" aria-label="Permalink to “2.3 混合（推荐）”">​</a></h3><p>一个简单可落地的分工：</p><ul><li><strong>本地模型</strong>：草稿、批量总结、结构化提取、离线使用</li><li><strong>云端强模型</strong>：最终润色、关键回答、复杂规划与推理</li></ul><h4 id="_2-3-1-混合的最小落地组合-你可以直接照抄" tabindex="-1">2.3.1 混合的最小落地组合（你可以直接照抄） <a class="header-anchor" href="#_2-3-1-混合的最小落地组合-你可以直接照抄" aria-label="Permalink to “2.3.1 混合的最小落地组合（你可以直接照抄）”">​</a></h4><ul><li><strong>本地</strong>：<code>Qwen2.5（中小尺寸）</code> 或 <code>Llama 3.x / Llama 4（中小尺寸）</code>（做草稿/批量/离线）</li><li><strong>云端</strong>：<code>GPT-4o</code> 或 <code>Claude 3.x</code>（做最终润色/关键推理/长文档）</li><li><strong>路由规则</strong>（最实用）： <ul><li>&quot;写简历/重要答复/复杂重构&quot; → 云端强模型</li><li>&quot;批量出题/结构化提取/生成初稿&quot; → 本地/性价比云端</li><li>&quot;隐私数据 / 离线任务&quot; → 本地模型</li></ul></li></ul><h2 id="_3-按使用场景给出-选型建议" tabindex="-1">3）按使用场景给出&quot;选型建议&quot; <a class="header-anchor" href="#_3-按使用场景给出-选型建议" aria-label="Permalink to “3）按使用场景给出&quot;选型建议&quot;”">​</a></h2><h3 id="_3-1-日常开发提效-写代码-解释报错" tabindex="-1">3.1 日常开发提效（写代码/解释报错） <a class="header-anchor" href="#_3-1-日常开发提效-写代码-解释报错" aria-label="Permalink to “3.1 日常开发提效（写代码/解释报错）”">​</a></h3><ul><li><strong>优先级</strong>：代码能力 &gt; 稳定性 &gt; 成本</li><li><strong>建议</strong>： <ul><li>云端强模型用于关键任务（重构、复杂问题）</li><li>本地模型用于快速问答、模板生成</li></ul></li></ul><p><strong>当下建议：</strong></p><ul><li><strong>云端首选</strong>：<code>GPT-4o</code> / <code>Claude 3.x</code>（关键任务）</li><li><strong>本地首选</strong>：<code>DeepSeek（代码向）</code> / <code>Qwen2.5</code> / <code>Llama 3.x</code>（日常与离线）</li></ul><h3 id="_3-2-文档写作-知识库-简历-面试稿" tabindex="-1">3.2 文档写作（知识库/简历/面试稿） <a class="header-anchor" href="#_3-2-文档写作-知识库-简历-面试稿" aria-label="Permalink to “3.2 文档写作（知识库/简历/面试稿）”">​</a></h3><ul><li><strong>优先级</strong>：表达质量 &gt; 结构化输出能力 &gt; 稳定性</li><li><strong>建议</strong>： <ul><li>先用本地模型出结构（目录/要点）</li><li>再用云端强模型做润色与统一口径</li></ul></li></ul><p><strong>当下建议：</strong></p><ul><li><strong>云端首选</strong>：<code>Claude 3.x</code>（长文档/表达一致性）+ <code>GPT-4o</code>（综合能力）</li><li><strong>本地首选</strong>：<code>Qwen2.5</code>（中文写作/结构化输出）或 <code>Llama 3.x</code></li></ul><h3 id="_3-3-图片生成大模型-ai-绘图-设计素材" tabindex="-1">3.3 图片生成大模型（AI 绘图/设计素材） <a class="header-anchor" href="#_3-3-图片生成大模型-ai-绘图-设计素材" aria-label="Permalink to “3.3 图片生成大模型（AI 绘图/设计素材）”">​</a></h3><ul><li><strong>优先级</strong>：画质精细度 &gt; 风格多样性 &gt; 生成速度 &gt; 成本</li><li><strong>适用场景</strong>：封面图、插画、海报、Logo、产品渲染、UI 素材、头像</li><li><strong>建议</strong>： <ul><li>商业/设计师场景：优先 Midjourney（画质天花板），追求细节用 Flux</li><li>开发/自动化场景：优先 DALL·E 3 / GPT-4o 原生生图（API 友好、格式稳定）</li><li>国内可用/中文友好：优先 Qwen-VL 生图、可灵（Kling）图片生成、通义万相</li><li>本地部署/离线：Stable Diffusion / SDXL / ComfyUI（需高端显卡 ≥ 16GB VRAM）</li></ul></li></ul><p><strong>当下建议：</strong></p><table tabindex="0"><thead><tr><th>模型</th><th>类型</th><th>特点</th><th>适用场景</th></tr></thead><tbody><tr><td><strong>GPT-4o 原生生图</strong></td><td>云端 API</td><td>多模态统一、指令遵循强、文字渲染准确</td><td>产品图、UI 设计、图文混排</td></tr><tr><td><strong>Midjourney V7</strong></td><td>云端 SaaS</td><td>艺术画质顶级、风格丰富</td><td>插画、概念图、海报、品牌素材</td></tr><tr><td><strong>Flux Pro / Dev</strong></td><td>云端 API + 本地</td><td>写实度高、手部细节好、开源可本地</td><td>写实人物、产品摄影风、本地部署</td></tr><tr><td><strong>DALL·E 3</strong></td><td>云端 API</td><td>OpenAI 生态集成、API 简单</td><td>简单图文场景、快速原型</td></tr><tr><td><strong>可灵（Kling）</strong></td><td>云端 API（国内）</td><td>国内可用、中文友好、视频模型同生态</td><td>中文场景、国内团队</td></tr><tr><td><strong>通义万相</strong></td><td>云端 API（国内）</td><td>阿里生态、性价比高、中文支持好</td><td>批量素材、国内业务</td></tr><tr><td><strong>SD XL / ComfyUI</strong></td><td>本地开源</td><td>免费、可定制、生态成熟</td><td>自定义训练、离线场景、隐私敏感</td></tr></tbody></table><blockquote><p><strong>避坑提示</strong>：2026 年图片生成已高度成熟，不要纠结&quot;选哪家&quot;，关键是 <strong>先选定一个跑通工作流</strong>。Midjourney 画质最好但无 API；GPT-4o 生图 API 友好适合自动化；Flux 适合追求写实 + 本地部署。</p></blockquote><h3 id="_3-4-视频生成大模型-ai-视频-动画" tabindex="-1">3.4 视频生成大模型（AI 视频/动画） <a class="header-anchor" href="#_3-4-视频生成大模型-ai-视频-动画" aria-label="Permalink to “3.4 视频生成大模型（AI 视频/动画）”">​</a></h3><ul><li><strong>优先级</strong>：画面连贯性 &gt; 分辨率/时长 &gt; 可控性 &gt; 成本</li><li><strong>适用场景</strong>：短视频、广告、产品演示、教学动画、社交媒体内容</li><li><strong>建议</strong>： <ul><li>高质量短片：优先 Sora / 可灵（画质与运动流畅度领先）</li><li>快速迭代/产品 demo：优先 Runway Gen-3 / Pika（上手快、API 友好）</li><li>国内可用：优先可灵（Kling）、海螺 AI（MiniMax）、Vidu</li><li>注意：视频生成目前成本较高，建议先用图片模型出关键帧，再用视频模型做&quot;图生视频&quot;</li></ul></li></ul><p><strong>当下建议：</strong></p><table tabindex="0"><thead><tr><th>模型</th><th>类型</th><th>特点</th><th>适用场景</th></tr></thead><tbody><tr><td><strong>Sora</strong></td><td>云端（OpenAI）</td><td>长时视频、物理理解强、画质高</td><td>高质量短片、创意视频</td></tr><tr><td><strong>可灵 1.6（Kling）</strong></td><td>云端 API（国内）</td><td>国内最强开源视频模型之一、中文友好</td><td>短视频、广告、国内场景</td></tr><tr><td><strong>Runway Gen-3 Alpha</strong></td><td>云端 API</td><td>上手快、运动控制好、API 稳定</td><td>产品 demo、快速迭代</td></tr><tr><td><strong>Pika 2.0</strong></td><td>云端 SaaS</td><td>操作简单、特效丰富、适合非专业用户</td><td>社交媒体、轻量创作</td></tr><tr><td><strong>Veo 2（Google）</strong></td><td>云端（Google）</td><td>Google 生态、画质出色</td><td>Google Cloud 集成场景</td></tr><tr><td><strong>海螺 AI（MiniMax）</strong></td><td>云端（国内）</td><td>国内可用、生成速度快</td><td>快速出片、国内团队</td></tr><tr><td><strong>Luma Dream Machine</strong></td><td>云端 SaaS</td><td>3D 感知好、运动自然</td><td>3D 风格、动画</td></tr><tr><td><strong>CogVideoX</strong></td><td>本地开源</td><td>免费、可本地部署（需高端显卡）</td><td>离线实验、自定义训练</td></tr></tbody></table><blockquote><p><strong>避坑提示</strong>：视频生成 2026 年仍在快速迭代，模型之间差异较大。<strong>核心原则</strong>：先用图片模型出关键帧（成本低、可控性强），再用视频模型做&quot;图生视频&quot;，效果远优于&quot;文生视频&quot;。预算有限时优先可灵（国内性价比最高）或 Runway（API 最成熟）。</p></blockquote><h3 id="_3-5-rag-知识库问答" tabindex="-1">3.5 RAG（知识库问答） <a class="header-anchor" href="#_3-5-rag-知识库问答" aria-label="Permalink to “3.5 RAG（知识库问答）”">​</a></h3><ul><li><strong>优先级</strong>：上下文长度 + 稳定性 &gt; 纯模型参数大小</li><li><strong>建议</strong>： <ul><li>不要把&quot;检索&quot;交给模型：检索交给你的系统（向量库/索引）</li><li>模型只负责&quot;基于检索片段回答&quot;</li></ul></li></ul><p><strong>当下建议：</strong></p><ul><li><strong>云端</strong>：<code>GPT-4o</code> / <code>Claude 3.x</code>（回答质量更稳）</li><li><strong>本地</strong>：<code>Qwen2.5</code> / <code>Llama 3.x</code>（配合检索片段足够好用）</li></ul><blockquote><p>RAG 的核心不是&quot;换更大模型&quot;，而是：切块、召回、重排、引用与拒答策略。</p></blockquote><h3 id="_3-6-agent-工具调用、多步任务" tabindex="-1">3.6 Agent（工具调用、多步任务） <a class="header-anchor" href="#_3-6-agent-工具调用、多步任务" aria-label="Permalink to “3.6 Agent（工具调用、多步任务）”">​</a></h3><ul><li><strong>优先级</strong>：稳定性（格式/函数调用） &gt; 推理能力 &gt; 成本</li><li><strong>建议</strong>： <ul><li>关键点是&quot;结构化输出/工具调用&quot;能力稳定</li><li>给 Agent 加：输出校验、重试、幂等、日志</li></ul></li></ul><p><strong>当下建议：</strong></p><ul><li><strong>云端优先</strong>：<code>GPT-4o</code> / <code>Claude 3.x</code>（工具调用与格式更稳定）</li><li><strong>本地备选</strong>：<code>Qwen2.5</code> / <code>Llama 3.x</code>（务必加&quot;输出校验 + 重试&quot;）</li></ul><h2 id="_4-你可以直接照抄的落地方案-最少折腾版" tabindex="-1">4）你可以直接照抄的落地方案（最少折腾版） <a class="header-anchor" href="#_4-你可以直接照抄的落地方案-最少折腾版" aria-label="Permalink to “4）你可以直接照抄的落地方案（最少折腾版）”">​</a></h2><h3 id="版本一-立刻能用" tabindex="-1">版本一（立刻能用） <a class="header-anchor" href="#版本一-立刻能用" aria-label="Permalink to “版本一（立刻能用）”">​</a></h3><ul><li><strong>主力</strong>：云端 API（<code>GPT-4o</code> 或 <code>DeepSeek</code>）+ 本地小模型做离线/批量</li><li><strong>辅助</strong>：<code>Ollama</code> + <code>Qwen 2.5</code>（本地实验）</li><li><strong>工具链</strong>：<code>Cursor</code> + <code>Continue</code></li></ul><h3 id="版本二-团队协作" tabindex="-1">版本二（团队协作） <a class="header-anchor" href="#版本二-团队协作" aria-label="Permalink to “版本二（团队协作）”">​</a></h3><ul><li><strong>主力</strong>：云端 API + <strong>LLM Gateway</strong>（统一切换、统一日志与重试）</li><li><strong>辅助</strong>：本地模型做离线/批量</li><li><strong>工具链</strong>：<code>Cursor</code> + <code>MCP Server</code> + 内部知识库</li></ul><h3 id="版本三-企业级" tabindex="-1">版本三（企业级） <a class="header-anchor" href="#版本三-企业级" aria-label="Permalink to “版本三（企业级）”">​</a></h3><ul><li><strong>主力</strong>：混合推理集群（自建 + 云端）；关键链路再做自建推理与成本优化</li><li><strong>辅助</strong>：模型路由 + <strong>A/B 测试</strong> + <strong>监控</strong></li><li><strong>工具链</strong>：自定义 Agent + <code>MCP</code> + RAG Pipeline</li></ul><h2 id="_5-我给你的-当前优先推荐-按你这个知识库-agent-学习路线" tabindex="-1">5）我给你的&quot;当前优先推荐&quot;（按你这个知识库/Agent 学习路线） <a class="header-anchor" href="#_5-我给你的-当前优先推荐-按你这个知识库-agent-学习路线" aria-label="Permalink to “5）我给你的&quot;当前优先推荐&quot;（按你这个知识库/Agent 学习路线）”">​</a></h2><table tabindex="0"><thead><tr><th>用途</th><th>推荐</th><th>理由</th></tr></thead><tbody><tr><td><strong>本地学习/实验</strong></td><td><code>Qwen 2.5</code>（14B）或 <code>Llama 4</code>（8B）</td><td>Ollama 一键部署，够用</td></tr><tr><td><strong>日常编码 Cursor</strong></td><td><code>GPT-4o</code> 或 <code>Claude</code></td><td>代码理解最稳定</td></tr><tr><td><strong>文档与笔记</strong></td><td><code>Claude</code></td><td>长文本写作质量高</td></tr><tr><td><strong>Agent 实验</strong></td><td><code>GPT-4o</code></td><td>函数调用最成熟</td></tr><tr><td><strong>纯云端最省心</strong></td><td><code>GPT-4o</code>（综合）或 <code>Claude 3.x</code>（长文档/写作）</td><td>少折腾</td></tr><tr><td><strong>纯本地最省心</strong></td><td><code>Qwen2.5</code>（中文/工具）或 <code>Llama 3.x</code>（通用/生态）</td><td>离线可用</td></tr><tr><td><strong>图片生成</strong></td><td><code>GPT-4o 原生生图</code> / <code>Midjourney</code>；国内 <code>可灵</code> / <code>通义万相</code></td><td>API 友好 vs 画质</td></tr><tr><td><strong>视频生成</strong></td><td><code>可灵</code> / <code>Runway Gen-3</code>；高质量短片 <code>Sora</code></td><td>性价比 vs 画质</td></tr></tbody></table><blockquote><p><strong>下一步</strong>：确定模型后，搭配 <a href="./dev-tools-selection.html">AI 开发工具选型</a> 完成工具链搭建。</p></blockquote>',78)])])}const b=o(l,[["render",a]]);export{h as __pageData,b as default};
